'use client';

import {useEffect, useRef, useState, type ReactNode} from 'react';
import {cva} from 'class-variance-authority';
import {Icon, Renew, ChartLine, DataTable} from '@/components/quartz/icon';
import type {Kind} from '@/lib/quartz/kind';
import {useOffscreen} from '@/lib/quartz/use-offscreen';
import {cn} from '@/lib/quartz/utils';
import {CHART_EMPTY, EMPTY_VALUE} from '@/lib/quartz/format';
import {Button, ButtonSize} from '@/components/quartz/ui/button';
import {SegmentedControl, SegmentedControlItem} from '@/components/quartz/ui/segmented-control';
import {Status} from '@/components/quartz/ui/status';
import {
  ChartContainer, ChartDataTable, ChartLegend, ChartSwatch, ChartTooltip, ChartTooltipContent, ChartTooltipRow, WithChart,
  chartLegendVariants, inkSteps, seriesTone, useChart, useElementDirection, useElementWidth, useOptionalChart, useRovingPoints,
  type ChartConfig, type ChartContextValue, type ChartDataTableColumn, type ChartDataTableProps, type ChartDataTableRow,
  type ChartLegendProps, type ChartSeriesConfig, type ChartTooltipProps,
} from '@/components/quartz/ui/chart-parts';
import {BarChart, ChartPlot, LineChart, type BarChartProps, type ChartPlotProps, type ChartScale, type LineChartProps} from '@/components/quartz/ui/chart-plot';
import {formatCompact, linearPath, monotonePath, niceScale, numberAt, stepPath, unitFormat, type ChartRow, type ChartUnit, type Curve} from '@/components/quartz/ui/chart-scale';
import {Sparkline, StatusBar, sparklineVariants, statusBarVariants, type SparklineProps, type StatusBarBucket, type StatusBarProps} from '@/components/quartz/ui/chart-strip';

// Quartz's chart: one component, <Chart type="line" | "bar" | "sparkline" | "status">, with the frame
// (title, loading, error, retry, empty), the legend, the tooltip and the data table built in (was Line
// chart, Bar chart, Sparkline, Status bar, Chart frame, Chart legend, Chart tooltip and Chart data table).
// Drawn in plain SVG: no chart library. The parts stay exported for a chart that needs its own layout.
//
// Colour means a kind, or warn and fail, and nothing else. Every line draws in its line step (--accent-line),
// which clears 3:1 on paper and on the well for every kind and both statuses. A bar is its mark step with a 2px cap
// in the line step on its value end, so the 3:1 edge lives in the cap. A series with no kind is ink, then ink at
// 66%; past two, they repeat dashed, because ink at 45% is 2.9:1. The active point is a square: round means a person.
//
// The detail that comes from the job: a chart holds its exact height in every state, and its loading
// silhouette is its own type (bars for bar, a line for line, cells for status), so a dashboard of eight
// charts never jumps as they load, and a person can tell which chart is which before data arrives. The
// axis, tooltip and table share one unit picked from the largest value (unit="duration" or "count").
//
// ChartPlot is the cartesian frame line and bar share: nice y ticks, gridlines in ink at 5%, the zero
// line at 8%, x labels that thin out to fit, one focusable column per x value (roving tabindex, arrow
// keys), a crosshair or band highlight, the portalled tooltip and a screen-reader table.
//
// Every chart keeps its data table, empty ones too: a chart with no rows has a table with one row that
// says so. Under dir="rtl" each chart reads right to left: x runs from the right, the y axis sits on the
// right and the side arrows follow the screen.
//
// The files: chart-scale.ts (ticks, formats, paths), chart-parts.tsx (config, tone, hooks, tooltip, table,
// legend), chart-plot.tsx (ChartPlot, line, bar), chart-strip.tsx (sparkline, status bar) and this one, the
// frame and Chart. Import everything from here.

// ---------- Frame ----------

// panel is the chart as a widget, so it takes the Panel's anatomy (ui/panel.tsx): a grey outer with the frame edge, the
// 40px header and the legend on the grey, the description and the plot in a white bordered body 4px in. plain has no
// chrome, for a chart inside a stat or a block that has its frame. `card` is the old name for panel.
const panelFrame = 'overflow-hidden bg-(--surface-frame) frame forced-colors:outline forced-colors:outline-1';
const chartFrameVariants = cva('flex min-w-0 flex-col', {
  variants: {
    variant: {
      panel: panelFrame,
      card: panelFrame,
      plain: 'gap-4',
    },
  },
  defaultVariants: {variant: 'panel'},
});

type ChartFrameStyle = 'panel' | 'plain';

type ChartFrameProps = Omit<React.ComponentProps<'section'>, 'title'> & {
  /** panel: the widget anatomy, with the frame edge. plain: no chrome. */
  frame?: ChartFrameStyle | 'card';
  /** @deprecated Use `frame`. `card` is `panel`. */
  variant?: ChartFrameStyle | 'card';
  title: ReactNode;
  description?: ReactNode;
  /** Controls at the top right: a range select, a menu. */
  actions?: ReactNode;
  /** Under the chart, usually a ChartLegend. */
  footer?: ReactNode;
  /** px. The body's height in every state. */
  height?: number;
  loading?: boolean;
  /** What failed. Shows the error state instead of the chart. */
  error?: ReactNode;
  onRetry?: () => void;
  /** True while a retry is running. */
  retrying?: boolean;
  /** No data. Pass the sentence to show: "No runs in the last 24 hours". */
  empty?: ReactNode;
  /** The data as a visible table (a ChartDataTable with visible). Adds a Chart / Table switch. */
  table?: ReactNode;
  /** The loading silhouette's shape: the chart's own type. */
  shape?: 'bar' | 'line' | 'status' | 'sparkline';
  /** A chart of one kind. */
  kind?: Kind;
  /** The data is still arriving: a running status in the header. */
  live?: boolean;
};

const silhouette = [38, 52, 44, 66, 58, 72, 49, 61, 80, 68, 74, 90];

/** The loading shape of each chart type, still and in the skeleton fill, so the chart is recognisable before data. */
function Silhouette({shape}: {shape: 'bar' | 'line' | 'status' | 'sparkline'}) {
  if (shape === 'bar') return <>{silhouette.map((h, i) => <span key={i} aria-hidden className="flex-1 bg-(--surface-skeleton) forced-colors:bg-[GrayText]" style={{height: `${h}%`}}/>)}</>;
  if (shape === 'status') return <span aria-hidden className="flex h-(--row-sm) w-full gap-0.5 self-center">{Array.from({length: 30}, (_, i) => <span key={i} className="min-w-1 flex-1 bg-cell-quiet forced-colors:bg-[GrayText]"/>)}</span>;
  const points = silhouette.map((h, i) => `${(i / (silhouette.length - 1)) * 100},${100 - h}`).join(' ');
  return <svg aria-hidden viewBox="0 0 100 100" preserveAspectRatio="none" className="size-full overflow-visible">
    <polyline points={points} fill="none" vectorEffect="non-scaling-stroke" strokeLinejoin="round" className="stroke-(--surface-skeleton) forced-colors:stroke-[GrayText]" style={{strokeWidth: shape === 'line' ? 'var(--space-1)' : 'var(--line-accent)'}}/>
  </svg>;
}

function ChartFrame({title, description, actions, footer, height = 200, loading, error, onRetry, retrying, empty, table, shape = 'bar', frame: frameProp, variant, kind, live, className, children, ...props}: ChartFrameProps) {
  const [view, setView] = useState<'chart' | 'table'>('chart');
  const state = loading ? 'loading' : error ? 'error' : empty ? 'empty' : 'ready';
  // Retry unmounts with the error. If it had focus, focus moves to the chart's title rather than the page.
  const titleRef = useRef<HTMLHeadingElement>(null);
  const retryFocused = useRef(false);
  useEffect(() => {
    if (state === 'error' || !retryFocused.current) return;
    retryFocused.current = false;
    if (!document.activeElement || document.activeElement === document.body) titleRef.current?.focus();
  }, [state]);
  const showTable = table && view === 'table' && state === 'ready';
  const card = (frameProp ?? variant ?? 'panel') !== 'plain';
  const frameRef = useOffscreen<HTMLElement>(!!live && card);

  return <section
    ref={frameRef}
    data-slot="chart-frame"
    data-state={state}
    data-kind={kind}
    data-status={state === 'error' ? 'fail' : undefined}
    aria-busy={loading || undefined}
    className={cn(chartFrameVariants({variant: card ? 'panel' : 'plain'}), className)}
    {...props}
  >
    <header data-slot="chart-frame-header" className={cn(card ? 'frame-head justify-between' : 'flex min-w-0 flex-wrap items-center justify-between gap-x-4 gap-y-2')}>
      <div className="flex min-w-0 flex-col gap-0.5">
        <h3 ref={titleRef} tabIndex={-1} data-slot="chart-frame-title" className={cn('type-label text-text-1', card && 'truncate')}>{title}</h3>
        {description && !card && <p data-slot="chart-frame-description" className="type-body-sm text-text-3">{description}</p>}
      </div>
      {(actions || table || live) && <div data-slot="chart-frame-actions" className="flex shrink-0 items-center gap-2">
        <ButtonSize size="xs">
          {live && <Status status="running" label="Live"/>}
          {actions}
        </ButtonSize>
        {table && <SegmentedControl size="xs" aria-label="View" value={view} onValueChange={next => setView(next as 'chart' | 'table')}>
          <SegmentedControlItem value="chart" aria-label="Chart"><Icon icon={ChartLine} size={16}/></SegmentedControlItem>
          <SegmentedControlItem value="table" aria-label="Table"><Icon icon={DataTable} size={16}/></SegmentedControlItem>
        </SegmentedControl>}
      </div>}
    </header>
    <div data-slot={card ? 'chart-frame-inset' : undefined} className={cn(card && 'frame mx-1 mb-1 min-w-0 bg-page [--frame-color:var(--line-row)] [--frame-radius:calc(var(--radius-frame)-4px)] has-[+[data-slot=chart-frame-footer]]:mb-0')}>
    {description && card && <p data-slot="chart-frame-description" className="px-4 pt-3 type-body-sm text-text-3">{description}</p>}
    <div data-slot="chart-frame-plot" className={cn('min-w-0', card && 'px-4 pt-3 pb-4')}>
    <div data-slot="chart-frame-body" className="relative min-w-0" style={showTable ? undefined : {height}}>
      {state === 'loading' && <div data-slot="chart-frame-loading" data-shape={shape} className="flex h-full items-end gap-1">
        <span className="sr-only">Loading {typeof title === 'string' ? title : 'chart'}</span>
        <Silhouette shape={shape}/>
      </div>}
      {/* Top-left in the chart's own frame, which keeps its height. */}
      {state === 'error' && <div role="status" className="flex h-full flex-col items-start gap-3 pt-1">
        <Status status="fail">{error}</Status>
        {onRetry && <Button size="sm" variant="secondary" pending={!!retrying} onFocus={() => { retryFocused.current = true; }} onBlur={event => { if (event.relatedTarget) retryFocused.current = false; }} onClick={onRetry}><Icon icon={Renew} size={16}/>Retry</Button>}
      </div>}
      {state === 'empty' && <div className="relative h-full type-body text-text-2">
        {empty}
        <span aria-hidden className="absolute inset-x-0 bottom-0 h-px bg-line-row"/>
      </div>}
      {state === 'ready' && (showTable ? table : children)}
    </div>
    </div>
    </div>
    {/* The footer keeps its room in every state, so the legend landing never moves what is below. */}
    {footer && !showTable && <footer data-slot="chart-frame-footer" aria-hidden={state !== 'ready' || undefined} inert={state !== 'ready' || undefined} className={cn('min-w-0', card && 'px-2 py-1.5', state !== 'ready' && 'invisible')}>{footer}</footer>}
  </section>;
}

// ---------- Chart ----------

type ChartCommon = {
  /** The chart's name: the frame title, the point group and the data table caption. */
  label: string;
  /** Shown above the chart. Leave out for a chart with no frame header. */
  title?: ReactNode;
  description?: ReactNode;
  /** Controls at the top end of the frame: a range select. */
  actions?: ReactNode;
  /** panel: the chart as a widget, in the Panel's anatomy (grey outer with the frame edge, white body). plain: no chrome, inside a stat or a block's frame. none: no frame at all (sparkline default). */
  frame?: 'panel' | 'plain' | 'none' | 'card';
  /** A chart of one kind ("Runs, 30 days" is run). */
  kind?: Kind;
  /** The data is still arriving: a running status in the header. */
  live?: boolean;
  /** px. The body holds it in every state. */
  height?: number;
  loading?: boolean;
  /** What failed. Shows the error state with Retry when onRetry is set. */
  error?: ReactNode;
  onRetry?: () => void;
  retrying?: boolean;
  /** The sentence for no data. Shown when data is empty. */
  empty?: ReactNode;
  /** Axis, tooltip and table share one unit picked from the largest value. */
  unit?: ChartUnit;
  valueFormat?: (value: number) => string;
  className?: string;
};

type CartesianChartProps = ChartCommon & {
  type: 'line' | 'bar';
  data: ChartRow[];
  /** The field that names each row on the x axis. */
  xKey: string;
  config: ChartConfig;
  series?: string[];
  xFormat?: (value: unknown, index: number) => string;
  /** Show the legend under the chart. On when there is more than one series. */
  legend?: boolean;
  /** Add a Chart / Table switch to the frame. */
  table?: boolean;
  /** Series switched off at first. */
  defaultHidden?: string[];
  /** line */
  curve?: Curve;
  area?: boolean;
  zero?: boolean;
  /** bar */
  stacked?: boolean;
};

type SparklineChartProps = ChartCommon & Omit<SparklineProps, 'label' | 'className' | 'size' | 'valueFormat'> & {
  type: 'sparkline';
  size?: SparklineProps['size'];
};

type StatusChartProps = ChartCommon & Omit<StatusBarProps, 'label' | 'className' | 'size' | 'data' | 'unit'> & {
  type: 'status';
  data: StatusBarBucket[];
  size?: StatusBarProps['size'];
  /** The noun for a bucket's count, singular and plural: ['run', 'runs']. */
  noun?: [string, string];
};

type ChartProps = CartesianChartProps | SparklineChartProps | StatusChartProps;

/** One chart: line, bar, sparkline or status buckets, with its frame states, legend, tooltip and table. */
function Chart(props: ChartProps) {
  const {type, label, title, description, actions, height, loading, error, onRetry, retrying, empty, unit, className} = props;
  const frameKind = props.type === 'line' || props.type === 'bar' ? props.kind : undefined;
  const live = props.live;
  const frameProp = props.frame ?? (type === 'sparkline' ? 'none' : 'panel');
  // `card` is the old name for panel.
  const frame = frameProp === 'card' ? 'panel' : frameProp;
  let values: number[];
  if (props.type === 'line' || props.type === 'bar') {
    const keys = props.series ?? Object.keys(props.config);
    values = [];
    for (const row of props.data as ChartRow[]) for (const key of keys) { const v = numberAt(row, key); if (v !== null) values.push(v); }
  } else if (props.type === 'sparkline') values = props.data.filter((v): v is number => typeof v === 'number');
  else values = (props.data as StatusBarBucket[]).map(b => b.count);
  const format = props.valueFormat ?? unitFormat(unit, values);
  const isEmpty = !loading && !error && props.data.length === 0;
  // An empty chart still has its table, one row saying so, for a screen reader; the sentence it shows is
  // hidden from one, so it is heard once.
  const emptyText = empty ?? CHART_EMPTY;
  const emptyColumns = props.type === 'line' || props.type === 'bar'
    ? (props.series ?? Object.keys(props.config)).map(key => ({key, label: props.config[key]?.label ?? key}))
    : props.type === 'status' ? [{key: 'count', label: 'Count'}, {key: 'status', label: 'Status'}] : [{key: 'v', label}];
  const emptyState = isEmpty
    ? <><span aria-hidden>{emptyText}</span><ChartDataTable caption={label} rowHeader={props.type === 'line' || props.type === 'bar' ? props.config[props.xKey]?.label ?? 'Date' : props.type === 'status' ? 'Bucket' : 'Point'} columns={emptyColumns} rows={[]} empty={emptyText}/></>
    : undefined;
  const bodyHeight = height ?? (type === 'status' ? (props.size === 'sm' ? 16 : props.size === 'lg' ? 40 : 32) + 24 : type === 'sparkline' ? 24 : 200);

  let chart: ReactNode;
  let footer: ReactNode = null;
  let tableNode: ReactNode = null;
  if (type === 'line' || type === 'bar') {
    const {data, xKey, config, series, xFormat, curve, area, zero, stacked, defaultHidden} = props;
    const shown = series ?? Object.keys(config);
    const showLegend = props.legend ?? shown.length > 1;
    chart = type === 'line'
      ? <LineChart data={data} xKey={xKey} series={series} label={label} height={bodyHeight} curve={curve} area={area} zero={zero} xFormat={xFormat} valueFormat={format} empty={empty}/>
      : <BarChart data={data} xKey={xKey} series={series} label={label} height={bodyHeight} stacked={stacked} xFormat={xFormat} valueFormat={format} empty={empty}/>;
    if (showLegend) footer = <ChartLegend series={series}/>;
    if (props.table) {
      const f = format ?? formatCompact;
      tableNode = <ChartDataTable visible caption={label} rowHeader={config[xKey]?.label ?? 'Date'} columns={shown.map(key => ({key, label: config[key]?.label ?? key}))}
        rows={data.map((row, i) => ({key: String(i), label: (xFormat ?? (v => String(v)))(row[xKey], i), values: Object.fromEntries(shown.map(key => { const v = numberAt(row, key); return [key, v === null ? EMPTY_VALUE : f(v)]; }))}))}/>;
    }
    const inner = <ChartFrame title={title ?? label} description={description} actions={actions} footer={footer} height={bodyHeight} loading={loading} error={error} onRetry={onRetry} retrying={retrying} empty={emptyState} table={tableNode} shape={type} frame={frame === 'panel' ? 'panel' : 'plain'} kind={frameKind} live={live} data-chart-type={type} className={className}>{chart}</ChartFrame>;
    return <ChartContainer config={config} defaultHidden={defaultHidden} className="min-w-0">{inner}</ChartContainer>;
  }

  if (props.type === 'sparkline') {
    const {data, kind, variant, area, end, labels, interactive, size} = props;
    chart = <Sparkline data={data} label={label} kind={kind} variant={variant} area={area} end={end} labels={labels} interactive={interactive} size={size} valueFormat={format} className={frame === 'none' ? className : 'w-full'}/>;
  } else if (props.type === 'status') {
    const {data, kind, noun, range, onBucketClick, size} = props;
    chart = <StatusBar data={data} label={label} kind={kind} unit={noun} range={range} onBucketClick={onBucketClick} size={size} className={frame === 'none' ? className : undefined}/>;
  }
  if (frame === 'none') {
    if (loading) return <span data-slot="chart-frame-loading" data-shape={type} aria-busy className={cn('inline-flex', type === 'sparkline' ? 'h-(--control-xs) w-24' : 'h-(--row-sm) w-full', className)} style={{height: type === 'status' ? bodyHeight - 24 : undefined}}><span className="sr-only">Loading {label}</span><Silhouette shape={type}/></span>;
    return chart;
  }
  return <ChartFrame title={title ?? label} description={description} actions={actions} height={bodyHeight} loading={loading} error={error} onRetry={onRetry} retrying={retrying} empty={emptyState} shape={type} frame={frame === 'panel' ? 'panel' : 'plain'} kind={props.kind} live={live} data-chart-type={type} className={className}>{chart}</ChartFrame>;
}

export {
  Chart, unitFormat,
  ChartContainer, ChartPlot, ChartSwatch, WithChart, useChart, useOptionalChart, useElementWidth, useElementDirection, useRovingPoints,
  seriesTone, inkSteps, niceScale, formatCompact, numberAt,
  ChartTooltip, ChartTooltipContent, ChartTooltipRow,
  ChartDataTable,
  ChartLegend, chartLegendVariants,
  LineChart, monotonePath, linearPath, stepPath,
  BarChart,
  Sparkline, sparklineVariants,
  StatusBar, statusBarVariants,
  ChartFrame, chartFrameVariants,
  type ChartProps, type ChartUnit, type ChartConfig, type ChartSeriesConfig, type ChartContextValue, type ChartRow, type ChartScale, type ChartPlotProps,
  type ChartTooltipProps, type ChartDataTableProps, type ChartDataTableColumn, type ChartDataTableRow, type ChartLegendProps,
  type LineChartProps, type Curve, type BarChartProps, type SparklineProps, type StatusBarProps, type StatusBarBucket, type ChartFrameProps,
};

import {countUnitFor, durationUnitFor, fixed} from '@/lib/quartz/format';

// The chart's arithmetic, apart from React: nice ticks, the axis formats, reading a value off a row and the
// line paths. chart.tsx re-exports all of it; this file is where it lives.

type ChartRow = Record<string, unknown>;

type ChartUnit = 'duration' | 'count';

type Curve = 'linear' | 'monotone' | 'step';

type Point = {x: number; y: number};

/** Ticks at 1, 2, 2.5 or 5 times a power of ten, covering [min, max]. A reversed extent is read the right way round. */
function niceScale(min: number, max: number, count = 4) {
  if (!Number.isFinite(min) || !Number.isFinite(max)) { min = 0; max = 1; }
  if (min > max) [min, max] = [max, min];
  count = Math.max(1, Math.round(count) || 1);
  if (min === max) { max = min === 0 ? 1 : min + Math.abs(min); }
  const raw = (max - min) / count;
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const n = raw / magnitude;
  const step = (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * magnitude;
  const lo = Math.floor(min / step) * step;
  const hi = Math.ceil(max / step) * step;
  const ticks: number[] = [];
  for (let t = lo; t <= hi + step / 2; t += step) ticks.push(Number(t.toPrecision(12)));
  return {min: lo, max: hi, ticks};
}

const compact = new Intl.NumberFormat('en-US', {notation: 'compact', maximumFractionDigits: 1});

/** 1.2k, 3.4M. The default axis format. */
function formatCompact(value: number) {
  return compact.format(value);
}

/** One unit for a whole axis, picked from the largest value: ms, s, min, h for durations; none, k, M for counts. */
function unitFormat(unit: ChartUnit | undefined, values: number[]): ((v: number) => string) | undefined {
  if (!unit) return undefined;
  // The unit is picked from the largest value as it will show, so 59,999ms is a minute, not 60.0s. A tick
  // takes one decimal under 10 and none above, decided after rounding, and zero never reads "-0".
  const {unit: name, size} = unit === 'duration' ? durationUnitFor(values) : countUnitFor(values);
  const plain = new Intl.NumberFormat('en-US', {maximumFractionDigits: 0, signDisplay: 'negative'});
  return v => {
    const x = v / size;
    if (size === 1) return `${unit === 'duration' ? fixed(x, 0) : plain.format(x)}${name}`;
    return `${fixed(x, Math.abs(Number(x.toFixed(1))) >= 10 ? 0 : 1)}${name}`;
  };
}

/** A row's value for a series, or null when it is missing or not a finite number. */
function numberAt(row: ChartRow | undefined, key: string): number | null {
  const v = row?.[key];
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

/** Monotone cubic (Fritsch–Carlson): smooth, but never overshoots a value the data does not have. */
function monotonePath(points: Point[]) {
  if (points.length < 3) return linearPath(points);
  const n = points.length;
  const dx: number[] = [], slope: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    dx.push(points[i + 1].x - points[i].x);
    slope.push((points[i + 1].y - points[i].y) / (dx[i] || 1));
  }
  const tangent = [slope[0]];
  for (let i = 1; i < n - 1; i++) tangent.push(slope[i - 1] * slope[i] <= 0 ? 0 : (slope[i - 1] + slope[i]) / 2);
  tangent.push(slope[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (slope[i] === 0) { tangent[i] = 0; tangent[i + 1] = 0; continue; }
    const a = tangent[i] / slope[i], b = tangent[i + 1] / slope[i], h = a * a + b * b;
    if (h > 9) { const t = 3 / Math.sqrt(h); tangent[i] = t * a * slope[i]; tangent[i + 1] = t * b * slope[i]; }
  }
  let d = `M${points[0].x},${points[0].y}`;
  for (let i = 0; i < n - 1; i++) {
    const p = points[i], q = points[i + 1], h = dx[i] / 3;
    d += `C${p.x + h},${p.y + tangent[i] * h},${q.x - h},${q.y - tangent[i + 1] * h},${q.x},${q.y}`;
  }
  return d;
}

function linearPath(points: Point[]) {
  return points.map((p, i) => `${i ? 'L' : 'M'}${p.x},${p.y}`).join('');
}

function stepPath(points: Point[]) {
  return points.map((p, i) => i ? `H${(points[i - 1].x + p.x) / 2}V${p.y}` : `M${p.x},${p.y}`).join('') + (points.length ? `H${points[points.length - 1].x}` : '');
}

export {
  niceScale, formatCompact, unitFormat, numberAt, monotonePath, linearPath, stepPath,
  type ChartRow, type ChartUnit, type Curve, type Point,
};

'use client';

import {createContext, memo, useCallback, useContext, useId, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode} from 'react';
import {createPortal} from 'react-dom';
import {cva, type VariantProps} from 'class-variance-authority';
import type {Kind} from '@/lib/quartz/kind';
import {useQuartzPortal} from '@/lib/quartz/portal';
import {useDomDirection} from '@/lib/quartz/direction';
import {useScrollTabStop} from '@/lib/quartz/scroll-focus';
import {cn} from '@/lib/quartz/utils';
import {CHART_EMPTY, EMPTY_VALUE} from '@/lib/quartz/format';

// The pieces every Quartz chart shares: the config and legend state (ChartContainer), each series' tone and
// swatch, the measuring and roving-focus hooks, the tooltip, the data table and the legend. chart.tsx
// re-exports all of it; this file is where it lives.

type ChartSeriesConfig = {
  /** The series name, in the legend, tooltip, table and every point's accessible name. */
  label: string;
  /** The kind this series shows. Sets its hue. Leave out and the series is ink at a stepped alpha. */
  kind?: Kind;
  /** A series of trouble (retried, failed runs) takes a reserved hue instead of a kind's. */
  status?: 'warn' | 'fail';
  /**
   * Draw the line dashed, with a hollow swatch: a cue that does not depend on hue. Use it when two series
   * on one chart have hues that are hard to tell apart at 2px, like agent and model.
   */
  dashed?: boolean;
};

type ChartConfig = Record<string, ChartSeriesConfig>;

type ChartContextValue = {
  config: ChartConfig;
  keys: string[];
  /** Series switched off in the legend. */
  hidden: ReadonlySet<string>;
  toggle: (key: string) => void;
  /** The series the legend is pointing at; the others dim. */
  highlight: string | null;
  setHighlight: (key: string | null) => void;
};

const ChartContext = createContext<ChartContextValue | null>(null);

/** The config, hidden series and highlight of the nearest ChartContainer. Throws outside one. */
function useChart() {
  const context = useContext(ChartContext);
  if (!context) throw new Error('useChart must be used within a <ChartContainer/>');
  return context;
}

function useOptionalChart() {
  return useContext(ChartContext);
}

type ChartContainerProps = React.ComponentProps<'div'> & {
  config: ChartConfig;
  /** Series that start switched off. */
  defaultHidden?: string[];
};

/** Holds the config and the legend state for the charts and legend inside it. */
function ChartContainer({config, defaultHidden, className, children, ...props}: ChartContainerProps) {
  const [hidden, setHidden] = useState<ReadonlySet<string>>(() => new Set(defaultHidden));
  const [highlight, setHighlight] = useState<string | null>(null);
  const toggle = useCallback((key: string) => setHidden(prev => {
    const next = new Set(prev);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  }), []);
  const value = useMemo(() => ({config, keys: Object.keys(config), hidden, toggle, highlight, setHighlight}), [config, hidden, toggle, highlight]);
  return <ChartContext.Provider value={value}>
    <div data-slot="chart" className={cn('flex w-full min-w-0 flex-col gap-4', className)} {...props}>{children}</div>
  </ChartContext.Provider>;
}

/** Wraps a chart in its own container when it was given a config and is not inside one. */
function WithChart({config, children}: {config?: ChartConfig; children: ReactNode}) {
  const context = useOptionalChart();
  if (context || !config) return children;
  return <ChartContainer config={config}>{children}</ChartContainer>;
}

// ---------- Tone ----------

/**
 * Ink steps for series with no kind. Only ink (17:1) and --chart-ink-2 (5.6:1) clear 3:1 on paper; ink at
 * 45% is 2.9:1, so a third and fourth kind-less series reuse the two steps with a dashed line instead.
 * Measured with ds-explore/color.mjs over paper and the grey card.
 */
const inkSteps = ['var(--ink)', 'var(--chart-ink-2)'] as const;

/** data-kind or data-status, the ink step and the dash for one series. Spread it on what draws the series. */
function seriesTone(config: ChartConfig, key: string): {'data-kind'?: Kind; 'data-status'?: 'warn' | 'fail'; 'data-dashed'?: ''; style?: CSSProperties} {
  const {kind, status, dashed: forced} = config[key] ?? {};
  const dash = forced ? {'data-dashed': '' as const} : {};
  if (status) return {'data-status': status, ...dash};
  if (kind) return {'data-kind': kind, ...dash};
  const inkIndex = Math.max(0, Object.keys(config).filter(k => !config[k].kind && !config[k].status).indexOf(key));
  const step = inkSteps[inkIndex % 2];
  const dashed = inkIndex >= 2 || forced ? {'data-dashed': '' as const} : {};
  return inkIndex % 2 === 0 ? dashed : {...dashed, style: {'--accent-mark': step, '--accent-line': step} as CSSProperties};
}

/** The series' square: 8px, square corners, the same mark as a status dot. */
function ChartSwatch({config, series, className}: {config: ChartConfig; series: string; className?: string}) {
  const tone = seriesTone(config, series);
  // The swatch is the series' line step, the colour that draws it; a dashed series shows a hollow square.
  return <span
    data-slot="chart-swatch"
    aria-hidden
    {...tone}
    className={cn('inline-block size-(--mark-size) shrink-0 forced-colors:bg-[CanvasText]', tone['data-dashed'] !== undefined ? 'shadow-[inset_0_0_0_2px_var(--accent-line)]' : 'bg-accent-line', className)}
  />;
}

// ---------- Hooks ----------

/** The width of an element, kept current with a ResizeObserver. 0 until it mounts. */
function useElementWidth<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setWidth(el.clientWidth);
    const observer = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)));
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  return [ref, width] as const;
}

/**
 * The element's own reading direction, so a chart under dir="rtl" mirrors whether or not a
 * DirectionProvider says so. 'ltr' until it mounts; read again only when a dir attribute changes.
 */
function useElementDirection(ref: React.RefObject<HTMLElement | null>): 'ltr' | 'rtl' {
  return useDomDirection(ref);
}

/**
 * Roving focus over a row of points. One point is in the tab order; arrow keys, Home and End move it.
 * In a right-to-left chart the side arrows follow the screen: Right moves to the point on the right.
 * Returns the key handler and the tabIndex for each index.
 */
function useRovingPoints(count: number, onMove: (index: number, el: HTMLElement | null) => void) {
  const [current, setCurrent] = useState(count - 1);
  const refs = useRef<(HTMLElement | null)[]>([]);
  const safe = Math.min(Math.max(current, 0), count - 1);
  const move = (index: number) => {
    const next = Math.min(Math.max(index, 0), count - 1);
    setCurrent(next);
    const el = refs.current[next];
    el?.focus();
    onMove(next, el ?? null);
  };
  const onKeyDown = (event: React.KeyboardEvent, index: number) => {
    const step = event.shiftKey ? 7 : 1;
    // Points run right to left in a right-to-left chart, so the side arrows swap; up and down keep their order.
    const back = getComputedStyle(event.currentTarget).direction === 'rtl' ? -1 : 1;
    const keys: Record<string, number> = {ArrowRight: index + step * back, ArrowDown: index + step, ArrowLeft: index - step * back, ArrowUp: index - step, Home: 0, End: count - 1};
    if (!(event.key in keys)) return;
    event.preventDefault();
    move(keys[event.key]);
  };
  return {
    current: safe,
    setCurrent,
    onKeyDown,
    tabIndex: (index: number) => (index === safe ? 0 : -1),
    ref: (index: number) => (el: HTMLElement | null) => { refs.current[index] = el; },
  };
}

// ---------- Tooltip ----------

const GAP = 8;
const EDGE = 8;

type ChartTooltipProps = {
  /** The point to point at, in viewport (client) pixels. null hides the tooltip. */
  anchor: {x: number; y: number} | null;
  children?: ReactNode;
  className?: string;
};

function ChartTooltip({anchor, children, className}: ChartTooltipProps) {
  const container = useQuartzPortal();
  const ref = useRef<HTMLDivElement>(null);
  const [place, setPlace] = useState<{left: number; top: number; side: 'top' | 'bottom'} | null>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!anchor || !el) { setPlace(null); return; }
    const {width, height} = el.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const side = anchor.y - GAP - height < EDGE ? 'bottom' : 'top';
    const top = side === 'top' ? anchor.y - GAP - height : anchor.y + GAP;
    const left = Math.min(Math.max(anchor.x - width / 2, EDGE), vw - width - EDGE);
    setPlace({left, top, side});
  }, [anchor, children]);

  if (!anchor || container === null) return null;
  const tooltip = <div
    ref={ref}
    data-slot="chart-tooltip"
    data-surface="inverse"
    data-side={place?.side}
    aria-hidden
    className={cn(
      'pointer-events-none fixed z-(--z-overlay) flex min-w-36 max-w-(--tooltip-max) flex-col gap-1.5 rounded-soft bg-page px-3 py-2 text-text-1 shadow-overlay',
      !place && 'invisible',
      className,
    )}
    style={{left: place?.left ?? 0, top: place?.top ?? 0}}
  >{children}</div>;
  return container ? createPortal(tooltip, container) : tooltip;
}

/** A title (the x value) over the rows. */
function ChartTooltipContent({title, children, className}: {title?: ReactNode; children?: ReactNode; className?: string}) {
  return <div data-slot="chart-tooltip-content" className={cn('flex flex-col gap-1', className)}>
    {title && <div data-slot="chart-tooltip-title" className="type-label-sm text-text-3">{title}</div>}
    {children}
  </div>;
}

/** One series: its swatch, its name and its value, the value right-aligned in tabular figures. */
function ChartTooltipRow({indicator, label, value, className}: {indicator?: ReactNode; label: ReactNode; value: ReactNode; className?: string}) {
  return <div data-slot="chart-tooltip-row" className={cn('flex items-center gap-2 type-label-sm', className)}>
    {indicator}
    <span className="min-w-0 flex-1 truncate text-text-2">{label}</span>
    <span className="data text-text-1">{value}</span>
  </div>;
}

// ---------- Data table ----------

type ChartDataTableColumn = {key: string; label: ReactNode};
type ChartDataTableRow = {key: string; label: ReactNode; values: Record<string, ReactNode>};

type ChartDataTableProps = {
  /** The table's name. Usually the chart title. */
  caption: ReactNode;
  /** The one row a table with no rows shows, so an empty chart still says so in its table. */
  empty?: ReactNode;
  /** The head of the first column, which names each row. */
  rowHeader?: ReactNode;
  columns: ChartDataTableColumn[];
  rows: ChartDataTableRow[];
  /** Show the table instead of hiding it for screen readers only. */
  visible?: boolean;
  className?: string;
};

const ChartDataTable = memo(function ChartDataTable({caption, rowHeader = 'Date', columns, rows, empty = CHART_EMPTY, visible, className}: ChartDataTableProps) {
  // A visible table scrolls past --popup-max; while it does, it takes a tab stop so a keyboard can scroll it.
  const box = useRef<HTMLDivElement>(null);
  const tab = useScrollTabStop(box, !!visible);
  // The scrolling region takes its name from the caption, whatever the caption holds: a string as the
  // label, anything else by reference.
  const captionId = useId();
  const named = tab === 0 ? (typeof caption === 'string' ? {'aria-label': caption} : {'aria-labelledby': captionId}) : {};
  return <div
    ref={box}
    data-slot="chart-data-table"
    data-visible={visible || undefined}
    tabIndex={tab}
    role={tab === 0 ? 'region' : undefined}
    {...named}
    className={cn(visible ? 'max-h-(--popup-max) overflow-auto bg-page' : 'sr-only', className)}
  >
    <table className="w-full text-start">
      <caption id={captionId} className={cn(visible ? 'px-4 py-2 text-start type-label text-text-1' : undefined)}>{caption}</caption>
      <thead>
        <tr>
          <th scope="col" className="sticky top-0 h-(--row-sm) bg-page px-4 text-start align-middle type-label-sm font-normal text-text-3 shadow-[inset_0_-1px_0_var(--line-row)]">{rowHeader}</th>
          {columns.map(column => <th key={column.key} scope="col" className="sticky top-0 h-(--row-sm) bg-page px-4 text-end align-middle type-label-sm font-normal text-text-3 shadow-[inset_0_-1px_0_var(--line-row)]">{column.label}</th>)}
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 && <tr data-slot="chart-data-table-empty" className="rule-row">
          <td colSpan={columns.length + 1} className="h-(--row-sm) px-4 text-start align-middle type-label-sm text-text-3">{empty}</td>
        </tr>}
        {rows.map(row => <tr key={row.key} className="rule-row">
          <th scope="row" className="h-(--row-sm) px-4 text-start align-middle type-label-sm font-normal whitespace-nowrap text-text-2">{row.label}</th>
          {columns.map(column => <td key={column.key} className="h-(--row-sm) px-4 text-end align-middle type-label-sm text-text-1">{row.values[column.key] ?? EMPTY_VALUE}</td>)}
        </tr>)}
      </tbody>
    </table>
  </div>;
});

// ---------- Legend ----------

const chartLegendVariants = cva('flex min-w-0', {
  variants: {
    layout: {
      row: 'flex-wrap items-center gap-x-1 gap-y-1',
      column: 'flex-col gap-0.5',
    },
  },
  defaultVariants: {layout: 'row'},
});

type ChartLegendProps = Omit<React.ComponentProps<'ul'>, 'children'> & VariantProps<typeof chartLegendVariants> & {
  /** Series to list. Defaults to every key in the config. */
  series?: string[];
  /** A value after each name, like the latest reading or a total. */
  values?: Record<string, ReactNode>;
  /** Let people switch series off. Off makes the legend a plain key. */
  toggle?: boolean;
};

function ChartLegend({series, values, toggle = true, layout = 'row', className, ...props}: ChartLegendProps) {
  const {config, keys, hidden, toggle: flip, highlight, setHighlight} = useChart();
  const list = series ?? keys;
  return <ul data-slot="chart-legend" data-layout={layout} className={cn(chartLegendVariants({layout}), className)} {...props}>
    {list.map(key => {
      const off = hidden.has(key);
      const dim = highlight !== null && highlight !== key;
      const body = <>
        <ChartSwatch config={config} series={key} className={cn(off && 'bg-transparent shadow-[inset_0_0_0_2px_var(--accent-line)]')}/>
        <span className={cn('min-w-0 truncate', off ? 'text-text-3' : 'text-text-1')}>{config[key]?.label ?? key}</span>
        {values?.[key] !== undefined && <span className="data ms-auto ps-2 text-text-2">{values[key]}</span>}
      </>;
      return <li key={key} className={cn('min-w-0 transition-opacity duration-(--dur-fast)', dim && 'opacity-(--dim-opacity)', layout === 'column' && 'w-full')}>
        {toggle
          ? <button
              type="button"
              data-slot="chart-legend-item"
              aria-pressed={!off}
              onClick={() => flip(key)}
              onPointerEnter={() => !off && setHighlight(key)}
              onPointerLeave={() => setHighlight(null)}
              onFocus={() => !off && setHighlight(key)}
              onBlur={() => setHighlight(null)}
              onKeyDown={event => { if (event.key === 'Escape') setHighlight(null); }}
              className="flex h-(--control-sm) w-full min-w-0 items-center gap-2 rounded-soft px-2 type-label transition-colors duration-(--dur-fast) ease-(--ease-step) hover:bg-hover"
            >{body}</button>
          : <span data-slot="chart-legend-item" className="flex h-(--control-sm) min-w-0 items-center gap-2 px-2 type-label">{body}</span>}
      </li>;
    })}
  </ul>;
}

export {
  ChartContainer, WithChart, useChart, useOptionalChart, useElementWidth, useElementDirection, useRovingPoints,
  seriesTone, inkSteps, ChartSwatch,
  ChartTooltip, ChartTooltipContent, ChartTooltipRow,
  ChartDataTable,
  ChartLegend, chartLegendVariants,
  type ChartConfig, type ChartSeriesConfig, type ChartContextValue,
  type ChartTooltipProps, type ChartDataTableProps, type ChartDataTableColumn, type ChartDataTableRow, type ChartLegendProps,
};

'use client';

import {useEffect, useRef, useState, type ReactNode} from 'react';
import {cn} from '@/lib/quartz/utils';
import {CHART_EMPTY, EMPTY_VALUE} from '@/lib/quartz/format';
import {cssNumber} from '@/lib/quartz/css-var';
import {
  ChartDataTable, ChartSwatch, ChartTooltip, ChartTooltipContent, ChartTooltipRow, WithChart,
  seriesTone, useChart, useElementDirection, useElementWidth, useRovingPoints, type ChartConfig,
} from '@/components/quartz/ui/chart-parts';
import {formatCompact, linearPath, monotonePath, niceScale, numberAt, stepPath, type ChartRow, type Curve, type Point} from '@/components/quartz/ui/chart-scale';

// ChartPlot, the cartesian frame line and bar share, and the line and bar charts drawn in it. chart.tsx
// re-exports all of it; this file is where it lives. In a right-to-left chart x runs right to left and the
// y axis sits on the right; the point buttons are a flex row, which the direction already reverses.

type ChartScale = {
  width: number;
  height: number;
  plot: {left: number; right: number; top: number; bottom: number};
  /** Centre of the x slot for a row index. */
  x: (index: number) => number;
  /** Pixel y for a value. */
  y: (value: number) => number;
  /** Width of one x slot. */
  band: number;
  /** The row under the pointer or focus. */
  active: number | null;
  /** The chart reads right to left: x(0) is at the right and the y axis on the right. */
  rtl: boolean;
};

type ChartPlotProps = {
  data: ChartRow[];
  /** The field that names each row on the x axis. */
  xKey: string;
  /** The series drawn, in order. */
  series: string[];
  config: ChartConfig;
  /** 'point' puts the first and last rows on the plot edges (lines); 'band' gives each row a slot (bars). */
  mode: 'point' | 'band';
  /** Smallest and largest value to fit. The scale rounds out to nice ticks. */
  extent: [number, number];
  height: number;
  /** The chart's name, for the point group and the table caption. */
  label: string;
  xFormat: (value: unknown, index: number) => string;
  valueFormat: (value: number) => string;
  /** Value text in the tooltip, table and accessible names. Defaults to valueFormat. */
  tooltipFormat?: (value: number) => string;
  /** A last tooltip row, like a stacked total. */
  tooltipFooter?: (row: ChartRow) => ReactNode;
  /** The series, drawn under the crosshair dots. */
  children: (scale: ChartScale) => ReactNode;
  /** What to draw over the series for the active row: dots on lines. */
  overlay?: (scale: ChartScale) => ReactNode;
  /** Text for a chart with no rows. */
  empty?: ReactNode;
  className?: string;
};

/** The fallback for --chart-axis-gap, which ChartPlot reads off its container. */
const AXIS_GAP = 8;
const X_LABEL_ROOM = 24;
const TICK_CHAR = 7;
const X_LABEL_MIN = 72;

/** The frame line, bar and custom x/y charts share: axes, grid, keyboard points, tooltip and table. */
function ChartPlot({data, xKey, series, config, mode, extent, height, label, xFormat, valueFormat, tooltipFormat = valueFormat, tooltipFooter, children, overlay, empty = CHART_EMPTY, className}: ChartPlotProps) {
  const [ref, width] = useElementWidth<HTMLDivElement>();
  const rtl = useElementDirection(ref) === 'rtl';
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<{x: number; y: number} | null>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const n = data.length;

  const scale = niceScale(extent[0], extent[1]);
  const tickLabels = scale.ticks.map(valueFormat);
  const gap = width ? cssNumber(ref.current, '--chart-axis-gap', AXIS_GAP) : AXIS_GAP;
  // The y axis takes the start side: the left, or the right in a right-to-left chart, where x runs right to left.
  const axisRoom = Math.max(...tickLabels.map(t => t.length)) * TICK_CHAR + gap;
  const endRoom = mode === 'point' ? gap : 0;
  const plot = rtl
    ? {left: endRoom, right: Math.max(endRoom + 1, width - axisRoom), top: gap, bottom: height - X_LABEL_ROOM}
    : {left: axisRoom, right: Math.max(axisRoom + 1, width - endRoom), top: gap, bottom: height - X_LABEL_ROOM};
  const plotWidth = plot.right - plot.left;
  const band = mode === 'band' ? plotWidth / Math.max(n, 1) : plotWidth / Math.max(n - 1, 1);
  const origin = rtl ? plot.right : plot.left;
  const forward = rtl ? -1 : 1;
  const x = (i: number) => mode === 'band' ? origin + forward * band * (i + 0.5) : n === 1 ? plot.left + plotWidth / 2 : origin + forward * band * i;
  const y = (v: number) => plot.bottom - ((v - scale.min) / (scale.max - scale.min)) * (plot.bottom - plot.top);
  const s: ChartScale = {width, height, plot, x, y, band, active, rtl};

  const anchorFor = (index: number) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) return null;
    const values = series.map(key => numberAt(data[index], key)).filter((v): v is number => v !== null);
    const top = values.length ? y(Math.max(...values)) : plot.top;
    return {x: rect.left + x(index), y: rect.top + Math.min(top, plot.bottom)};
  };
  const show = (index: number) => { setActive(index); setAnchor(anchorFor(index)); };
  const hide = () => { setActive(null); setAnchor(null); };
  const roving = useRovingPoints(n, index => show(index));

  // A pointer tooltip would drift from its point on scroll, so it closes.
  useEffect(() => {
    if (active === null) return;
    const close = () => { if (!ref.current?.contains(document.activeElement)) hide(); };
    window.addEventListener('scroll', close, {capture: true, passive: true});
    return () => window.removeEventListener('scroll', close, {capture: true});
  }, [active, ref]);

  const xLabelEvery = Math.max(1, Math.ceil(n / Math.max(1, Math.floor(plotWidth / X_LABEL_MIN))));
  const pointName = (index: number) => {
    const row = data[index];
    const values = series.map(key => {
      const v = numberAt(row, key);
      return `${config[key]?.label ?? key} ${v === null ? 'no data' : tooltipFormat(v)}`;
    });
    return `${xFormat(row?.[xKey], index)}: ${values.join(', ')}`;
  };

  const table = <ChartDataTable
    caption={label}
    empty={empty}
    rowHeader={config[xKey]?.label ?? 'Date'}
    columns={series.map(key => ({key, label: config[key]?.label ?? key}))}
    rows={data.map((row, i) => ({key: String(i), label: xFormat(row[xKey], i), values: Object.fromEntries(series.map(key => {
      const v = numberAt(row, key);
      return [key, v === null ? EMPTY_VALUE : tooltipFormat(v)];
    }))}))}
  />;

  // No rows: the message, and the table still there for a screen reader, saying the same in its one row.
  if (n === 0) {
    return <div ref={ref} data-slot="chart-plot" className={cn('relative type-body text-text-2', className)} style={{height}}>
      {table}
      <span aria-hidden className="block pt-3">{empty}</span>
      {/* The x axis's place, so an empty chart keeps its shape. */}
      <span aria-hidden className="absolute inset-x-0 bottom-0 h-px bg-line-row"/>
    </div>;
  }

  return <div ref={ref} data-slot="chart-plot" className={cn('relative w-full min-w-0', className)} style={{height}}>
    {table}
    {width > 0 && <>
      {/* Coordinates are physical, mirrored above for right to left, so the drawing itself stays left to right. */}
      <svg ref={svgRef} aria-hidden direction="ltr" width={width} height={height} className="block overflow-visible">
        {mode === 'band' && active !== null && <rect x={x(active) - band / 2} y={plot.top} width={band} height={plot.bottom - plot.top} className="fill-hover"/>}
        {scale.ticks.map((tick, i) => <g key={tick}>
          <line x1={plot.left} x2={plot.right} y1={y(tick)} y2={y(tick)} className={tick === 0 ? 'stroke-line-row' : 'stroke-faint'} style={{strokeWidth: 'var(--line-hair)'}} shapeRendering="crispEdges"/>
          <text x={rtl ? plot.right + gap : plot.left - gap} y={y(tick)} dy="0.32em" textAnchor={rtl ? 'start' : 'end'} className="fill-text-3 type-label-sm">{tickLabels[i]}</text>
        </g>)}
        {data.map((row, i) => {
          if ((n - 1 - i) % xLabelEvery !== 0) return null;
          // The last label hangs inward from the edge, so a label within one label's room of it would overlap it.
          if (mode === 'point' && i !== n - 1 && Math.abs(x(n - 1) - x(i)) < X_LABEL_MIN) return null;
          // The first label hangs inward from the start edge and the last from the end edge.
          const first = rtl ? 'end' : 'start', last = rtl ? 'start' : 'end';
          const anchorAt = mode === 'point' && n > 1 ? (i === 0 ? first : i === n - 1 ? last : 'middle') : 'middle';
          return <text key={i} x={x(i)} y={height - 6} textAnchor={anchorAt} className="fill-text-3 type-label-sm">{xFormat(row[xKey], i)}</text>;
        })}
        {mode === 'point' && active !== null && <line x1={x(active)} x2={x(active)} y1={plot.top} y2={plot.bottom} className="stroke-text-1" style={{strokeWidth: 'var(--line-hair)'}} shapeRendering="crispEdges"/>}
        {children(s)}
        {overlay?.(s)}
      </svg>
      <div
        role="group"
        aria-label={label}
        aria-roledescription="chart"
        className="absolute flex"
        // Bands and a lone point (drawn at the plot's centre) take the plot exactly; otherwise each point's
        // hit area is centred on it, half a step past each end.
        style={{left: mode === 'band' || n === 1 ? plot.left : plot.left - band / 2, top: plot.top, width: mode === 'band' || n === 1 ? plotWidth : plotWidth + band, height: plot.bottom - plot.top}}
        onPointerLeave={() => { if (!ref.current?.contains(document.activeElement)) hide(); }}
      >
        {data.map((_, i) => <button
          key={i}
          ref={roving.ref(i)}
          type="button"
          tabIndex={roving.tabIndex(i)}
          aria-label={pointName(i)}
          onPointerEnter={() => { roving.setCurrent(i); show(i); }}
          onFocus={() => { roving.setCurrent(i); show(i); }}
          onBlur={event => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node)) hide(); }}
          onKeyDown={event => { if (event.key === 'Escape') hide(); else roving.onKeyDown(event, i); }}
          className="h-full min-w-0 flex-1 cursor-crosshair rounded-inner focus-visible:focus-ring-inset"
        />)}
      </div>
      <ChartTooltip anchor={active !== null ? anchor : null}>
        {active !== null && <ChartTooltipContent title={xFormat(data[active]?.[xKey], active)}>
          {series.map(key => {
            const v = numberAt(data[active], key);
            return <ChartTooltipRow key={key} indicator={<ChartSwatch config={config} series={key}/>} label={config[key]?.label ?? key} value={v === null ? EMPTY_VALUE : tooltipFormat(v)}/>;
          })}
          {tooltipFooter?.(data[active])}
        </ChartTooltipContent>}
      </ChartTooltip>
    </>}
  </div>;
}

// ---------- Line ----------

type LineChartProps = {
  data: ChartRow[];
  /** The field that names each row on the x axis, usually a date. */
  xKey: string;
  /** Series to draw. Defaults to every key in the config, minus the ones the legend hid. */
  series?: string[];
  /** Pass a config to use the chart on its own. Inside a ChartContainer it reads the container's. */
  config?: ChartConfig;
  /** The chart's name, for the point group and the data table. */
  label: string;
  /** px. */
  height?: number;
  curve?: Curve;
  /** A flat wash under the line. For a single series only. */
  area?: boolean;
  /** Start the y axis at zero. Turn off for values that sit far from zero, like latency percentiles. */
  zero?: boolean;
  xFormat?: (value: unknown, index: number) => string;
  valueFormat?: (value: number) => string;
  tooltipFormat?: (value: number) => string;
  /** Text for a chart with no rows. */
  empty?: React.ReactNode;
  className?: string;
};

const paths = {linear: linearPath, monotone: monotonePath, step: stepPath};

/** Runs of consecutive points with a value. A gap in the data is a gap in the line. */
function runs(data: ChartRow[], key: string, x: (i: number) => number, y: (v: number) => number) {
  const out: Point[][] = [];
  let current: Point[] = [];
  data.forEach((row, i) => {
    const v = numberAt(row, key);
    if (v === null) { if (current.length) out.push(current); current = []; return; }
    current.push({x: x(i), y: y(v)});
  });
  if (current.length) out.push(current);
  return out;
}

function LineChartPlot({data, xKey, series, label, height = 200, curve = 'monotone', area, zero = true, xFormat = v => String(v), valueFormat = formatCompact, tooltipFormat, empty, className}: Omit<LineChartProps, 'config'>) {
  const {config, keys, hidden, highlight} = useChart();
  const shown = (series ?? keys).filter(key => !hidden.has(key));
  const values = data.flatMap(row => shown.map(key => numberAt(row, key)).filter((v): v is number => v !== null));
  const extent: [number, number] = [zero ? Math.min(0, ...values) : Math.min(...values), Math.max(...values, zero ? 0 : -Infinity)];
  const toPath = paths[curve];

  return <ChartPlot
    data={data} xKey={xKey} series={shown} config={config} mode="point" extent={extent} height={height} label={label}
    xFormat={xFormat} valueFormat={valueFormat} tooltipFormat={tooltipFormat} empty={empty} className={className}
    overlay={s => s.active !== null && shown.map(key => {
      const v = numberAt(data[s.active!], key);
      if (v === null) return null;
      return <g key={key} {...seriesTone(config, key)}>
        {/* The active point is a square: round means a person. */}
        <rect x={s.x(s.active!) - 4} y={s.y(v) - 4} width={8} height={8} className="fill-accent-line stroke-page" style={{strokeWidth: 'var(--line-accent)'}}/>
      </g>;
    })}
  >
    {s => shown.map(key => {
      const tone = seriesTone(config, key);
      const segments = runs(data, key, s.x, s.y);
      const dim = highlight !== null && highlight !== key;
      const base = Math.min(Math.max(s.y(0), s.plot.top), s.plot.bottom);
      return <g key={key} data-slot="line-chart-series" data-series={key} {...tone} className={cn('transition-opacity duration-(--dur-fast)', dim && 'opacity-(--dim-opacity)')}>
        {area && shown.length === 1 && segments.map((pts, i) => pts.length > 1 && <path
          key={`a${i}`}
          d={`${toPath(pts)}L${pts[pts.length - 1].x},${base}L${pts[0].x},${base}Z`}
          className="fill-accent-wash stroke-none"
        />)}
        {segments.map((pts, i) => pts.length === 1
          ? <rect key={i} x={pts[0].x - 2} y={pts[0].y - 2} width={4} height={4} className="fill-accent-line"/>
          : <path key={i} d={toPath(pts)} fill="none" className="stroke-accent-line forced-colors:stroke-[CanvasText]" style={{strokeWidth: 'var(--line-accent)', strokeDasharray: tone['data-dashed'] !== undefined ? 'var(--chart-dash)' : undefined}} strokeLinejoin="round" strokeLinecap="round"/>)}
      </g>;
    })}
  </ChartPlot>;
}

/** Values over time. Inside a ChartContainer it shares the container's config and legend. */
function LineChart({config, ...props}: LineChartProps) {
  return <WithChart config={config}><LineChartPlot {...props}/></WithChart>;
}

// ---------- Bar ----------

type BarChartProps = {
  data: ChartRow[];
  /** The field that names each bucket on the x axis. */
  xKey: string;
  /** Series to draw. Defaults to every key in the config, minus the ones the legend hid. */
  series?: string[];
  /** Pass a config to use the chart on its own. Inside a ChartContainer it reads the container's. */
  config?: ChartConfig;
  label: string;
  /** px. */
  height?: number;
  /** Stack the series in each bucket instead of setting them side by side. */
  stacked?: boolean;
  /** The bucket the bars fill, 0 to 1. The rest is the gap between buckets. */
  fill?: number;
  xFormat?: (value: unknown, index: number) => string;
  valueFormat?: (value: number) => string;
  tooltipFormat?: (value: number) => string;
  /** Text for a chart with no rows. */
  empty?: React.ReactNode;
  /** Show a total row in the tooltip of a stacked chart. On by default when stacked. */
  total?: boolean;
  className?: string;
};

const SEGMENT_GAP = 1;
const GROUP_GAP = 1;
/** A bar's cap: the 2px of --line-accent on its value end, in the line step, so the bar's 3:1 edge is drawn there. */
const CAP = 2;

/**
 * One bar or stacked segment: the body in the series' mark step with a cap in its line step on the value end (the top
 * of a positive value, the bottom of a negative one). Each stacked segment carries its own cap, so kinds stay apart.
 */
function CappedBar({x, width, y, height, up, className, ...props}: Omit<React.SVGProps<SVGRectElement>, 'x' | 'y' | 'width' | 'height'> & {x: number; width: number; y: number; height: number; up: boolean}) {
  const cap = Math.min(height, CAP);
  return <>
    <rect x={x} width={width} y={y} height={height} shapeRendering="crispEdges" className={cn('fill-accent-mark forced-colors:fill-[CanvasText]', className)} {...props}/>
    {cap > 0 && <rect aria-hidden x={x} width={width} y={up ? y : y + height - cap} height={cap} shapeRendering="crispEdges" className={cn('pointer-events-none fill-accent-line forced-colors:fill-[CanvasText]', className)}/>}
  </>;
}

function BarChartPlot({data, xKey, series, label, height = 200, stacked, fill = 0.72, xFormat = v => String(v), valueFormat = formatCompact, tooltipFormat, total = stacked, empty, className}: Omit<BarChartProps, 'config'>) {
  const {config, keys, hidden, highlight} = useChart();
  const shown = (series ?? keys).filter(key => !hidden.has(key));
  const sum = (row: ChartRow, sign: 1 | -1) => shown.reduce((acc, key) => {
    const v = numberAt(row, key) ?? 0;
    return sign > 0 ? acc + Math.max(v, 0) : acc + Math.min(v, 0);
  }, 0);
  const values = stacked
    ? data.flatMap(row => [sum(row, 1), sum(row, -1)])
    : data.flatMap(row => shown.map(key => numberAt(row, key) ?? 0));
  const extent: [number, number] = [Math.min(0, ...values), Math.max(0, ...values)];
  const format = tooltipFormat ?? valueFormat;

  return <ChartPlot
    data={data} xKey={xKey} series={shown} config={config} mode="band" extent={extent} height={height} label={label}
    xFormat={xFormat} valueFormat={valueFormat} tooltipFormat={tooltipFormat} empty={empty} className={className}
    tooltipFooter={total && shown.length > 1 ? row => <ChartTooltipRow className="pt-1 rule-top" label="Total" value={format(sum(row, 1) + sum(row, -1))}/> : undefined}
  >
    {s => {
      const width = Math.max(1, s.band * fill);
      const zero = s.y(0);
      if (stacked) {
        return data.map((row, i) => {
          let up = 0, down = 0;
          const x0 = s.x(i) - width / 2;
          return <g key={i}>
            {shown.map(key => {
              const v = numberAt(row, key);
              if (!v) return null;
              const from = v > 0 ? up : down;
              const to = from + v;
              if (v > 0) up = to; else down = to;
              const top = Math.min(s.y(from), s.y(to));
              const h = Math.abs(s.y(to) - s.y(from)) - (from === 0 ? 0 : SEGMENT_GAP);
              const dim = highlight !== null && highlight !== key;
              return <g key={key} {...seriesTone(config, key)}>
                <CappedBar
                  data-series={key}
                  x={x0} width={width}
                  y={v > 0 ? top : top + (from === 0 ? 0 : SEGMENT_GAP)}
                  height={Math.max(h, 1)}
                  up={v > 0}
                  className={cn('transition-opacity duration-(--dur-fast) ease-(--ease-step)', dim && 'opacity-(--dim-opacity)')}
                />
              </g>;
            })}
          </g>;
        });
      }
      const each = (width - GROUP_GAP * (shown.length - 1)) / Math.max(shown.length, 1);
      return data.map((row, i) => <g key={i}>
        {shown.map((key, j) => {
          const v = numberAt(row, key);
          if (v === null) return null;
          const dim = highlight !== null && highlight !== key;
          return <g key={key} {...seriesTone(config, key)}>
            <CappedBar
              data-series={key}
              // The first series leads from the start side: the right in a right-to-left chart.
              x={s.x(i) - width / 2 + (s.rtl ? shown.length - 1 - j : j) * (each + GROUP_GAP)}
              width={Math.max(each, 1)}
              y={Math.min(s.y(v), zero)}
              height={Math.max(Math.abs(zero - s.y(v)), v === 0 ? 0 : 1)}
              up={v >= 0}
              className={cn('transition-opacity duration-(--dur-fast) ease-(--ease-step)', dim && 'opacity-(--dim-opacity)')}
            />
          </g>;
        })}
      </g>);
    }}
  </ChartPlot>;
}

/** Counts per bucket, grouped or stacked. Inside a ChartContainer it shares the container's legend. */
function BarChart({config, ...props}: BarChartProps) {
  return <WithChart config={config}><BarChartPlot {...props}/></WithChart>;
}

export {
  ChartPlot, LineChart, BarChart,
  type ChartScale, type ChartPlotProps, type LineChartProps, type BarChartProps,
};

'use client';

import {useRef, useState} from 'react';
import {cva, type VariantProps} from 'class-variance-authority';
import type {Kind} from '@/lib/quartz/kind';
import {cn} from '@/lib/quartz/utils';
import {CHART_EMPTY, EMPTY_VALUE} from '@/lib/quartz/format';
import {ChartDataTable, ChartTooltip, ChartTooltipContent, ChartTooltipRow, useElementWidth, useRovingPoints} from '@/components/quartz/ui/chart-parts';
import {Status} from '@/components/quartz/ui/status';

// The two charts that are a strip rather than a plot: the sparkline beside a number and the status bar of
// buckets. chart.tsx re-exports both; this file is where they live. Both read right to left under
// dir="rtl": the status cells are a flex row, and the sparkline mirrors its drawing.

// ---------- Sparkline ----------

const sparklineVariants = cva('relative inline-block min-w-0 align-middle', {
  variants: {
    size: {
      sm: 'h-4',
      default: 'h-(--control-xs)',
      lg: 'h-(--row-sm)',
    },
  },
  defaultVariants: {size: 'default'},
});

type SparklineProps = Omit<React.ComponentProps<'div'>, 'children'> & VariantProps<typeof sparklineVariants> & {
  /** Values in order, oldest first. null is a gap. */
  data: (number | null)[];
  /** What the values are: "Runs per hour". Names the table and the points. */
  label: string;
  /** The kind the values belong to. Sets the hue; ink without one. */
  kind?: Kind;
  variant?: 'line' | 'bar';
  /** A flat wash under the line. */
  area?: boolean;
  /** Mark the last value. On for lines. */
  end?: boolean;
  /** Names for each point, for the table and tooltip: dates or bucket labels. */
  labels?: string[];
  valueFormat?: (value: number) => string;
  /** Focus and hover each point, with a tooltip. */
  interactive?: boolean;
};

const VIEW_H = 100;
const PAD = 8;

/** The sentence a screen reader hears for the values: "up from 412 to 549, low 401, high 549". */
function trendWords(values: number[], format: (v: number) => string) {
  if (!values.length) return 'no data';
  const first = values[0], last = values[values.length - 1];
  const direction = last > first ? 'up' : last < first ? 'down' : 'flat';
  return `${direction} from ${format(first)} to ${format(last)}, low ${format(Math.min(...values))}, high ${format(Math.max(...values))}`;
}

function Sparkline({data, label, kind, variant = 'line', area, end = variant === 'line', labels, valueFormat = v => v.toLocaleString('en-US'), interactive, size = 'default', className, ...props}: SparklineProps) {
  const values = data.filter((v): v is number => v !== null && Number.isFinite(v));
  const n = data.length;
  const lo = variant === 'bar' ? Math.min(0, ...values) : Math.min(...values);
  const hi = Math.max(...values, lo + 1);
  const viewW = Math.max(n - 1, 1) * 10;
  const y = (v: number) => PAD + (1 - (v - lo) / (hi - lo || 1)) * (VIEW_H - PAD * 2);
  const x = (i: number) => variant === 'bar' ? (i + 0.5) * (viewW / n) : n === 1 ? viewW / 2 : (i / (n - 1)) * viewW;
  const nameAt = (i: number) => labels?.[i] ?? `Point ${i + 1}`;

  const segments: {x: number; y: number}[][] = [];
  let run: {x: number; y: number}[] = [];
  data.forEach((v, i) => {
    if (v === null || !Number.isFinite(v)) { if (run.length) segments.push(run); run = []; return; }
    run.push({x: x(i), y: y(v)});
  });
  if (run.length) segments.push(run);

  const lastIndex = data.findLastIndex(v => v !== null && Number.isFinite(v));
  const svgRef = useRef<SVGSVGElement>(null);
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<{x: number; y: number} | null>(null);
  const show = (i: number) => {
    setActive(i);
    const svg = svgRef.current;
    const rect = svg?.getBoundingClientRect();
    const v = data[i];
    if (!svg || !rect) return;
    // The drawing is mirrored in a right-to-left sparkline, so its points count from the right edge.
    const along = (x(i) / viewW) * rect.width;
    const rtl = getComputedStyle(svg).direction === 'rtl';
    setAnchor({x: rtl ? rect.right - along : rect.left + along, y: rect.top + ((v === null ? VIEW_H : y(v)) / VIEW_H) * rect.height});
  };
  const hide = () => { setActive(null); setAnchor(null); };
  const roving = useRovingPoints(n, i => show(i));
  const pct = (px: number, total: number) => `${(px / total) * 100}%`;

  // A div, not a span: it holds the data table. It stays inline-block, so it still sits in a line of text; do not put it inside a <p>.
  return <div data-slot="sparkline" data-kind={kind} data-variant={variant} className={cn(sparklineVariants({size}), 'w-24', className)} {...props}>
    <ChartDataTable
      caption={`${label}: ${trendWords(values, valueFormat)}`}
      empty={CHART_EMPTY}
      rowHeader="Point"
      columns={[{key: 'v', label}]}
      rows={data.map((v, i) => ({key: String(i), label: nameAt(i), values: {v: v === null ? EMPTY_VALUE : valueFormat(v)}}))}
    />
    {/* Right to left mirrors the drawing, which has no text, so the first value sits at the right like the first point button. */}
    <svg ref={svgRef} aria-hidden viewBox={`0 0 ${viewW} ${VIEW_H}`} preserveAspectRatio="none" className="block size-full overflow-visible rtl:-scale-x-100">
      {variant === 'bar'
        ? data.map((v, i) => v !== null && Number.isFinite(v) && <rect key={i} x={x(i) - (viewW / n) * 0.35} width={(viewW / n) * 0.7} y={Math.min(y(v), y(0))} height={Math.max(Math.abs(y(0) - y(v)), 2)} className={cn('fill-accent-line', active !== null && active !== i && 'opacity-40')}/>)
        : <>
            {area && segments.map((pts, i) => pts.length > 1 && <path key={`a${i}`} d={`M${pts[0].x},${VIEW_H}${pts.map(p => `L${p.x},${p.y}`).join('')}L${pts[pts.length - 1].x},${VIEW_H}Z`} className="fill-accent-wash"/>)}
            {/* A point with gaps on both sides is a dot, as in LineChart: a zero-length stroke with round caps, so
                the stretched viewBox cannot squash it into an oval. */}
            {segments.map((pts, i) => pts.length === 1 && <path key={`d${i}`} d={`M${pts[0].x},${pts[0].y}h0`} fill="none" vectorEffect="non-scaling-stroke" strokeLinecap="round" className="stroke-accent-line" style={{strokeWidth: 'var(--space-1)'}}/>)}
            {segments.map((pts, i) => pts.length > 1 && <path key={i} d={pts.map((p, j) => `${j ? 'L' : 'M'}${p.x},${p.y}`).join('')} fill="none" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" className="stroke-accent-line" style={{strokeWidth: size === 'sm' ? 'var(--line-hair)' : 'var(--line-accent)'}}/>)}
          </>}
    </svg>
    {variant === 'line' && (active ?? (end ? lastIndex : -1)) >= 0 && (() => {
      const i = active ?? lastIndex;
      const v = data[i];
      if (v === null || !Number.isFinite(v)) return null;
      return <span aria-hidden data-slot="sparkline-end" className="pointer-events-none absolute size-1.5 -translate-x-1/2 -translate-y-1/2 bg-accent-line rtl:translate-x-1/2" style={{insetInlineStart: pct(x(i), viewW), top: pct(y(v), VIEW_H)}}/>;
    })()}
    {interactive && n > 0 && <>
      <span role="group" aria-label={label} aria-roledescription="chart" className="absolute inset-0 flex" onPointerLeave={hide}>
        {data.map((v, i) => <button
          key={i}
          ref={roving.ref(i)}
          type="button"
          tabIndex={roving.tabIndex(i)}
          aria-label={`${nameAt(i)}: ${v === null ? 'no data' : valueFormat(v)}`}
          onPointerEnter={() => { roving.setCurrent(i); show(i); }}
          onFocus={() => { roving.setCurrent(i); show(i); }}
          onBlur={event => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node)) hide(); }}
          onKeyDown={event => { if (event.key === 'Escape') hide(); else roving.onKeyDown(event, i); }}
          className="h-full min-w-0 flex-1 rounded-inner focus-visible:focus-ring-inset"
        />)}
      </span>
      <ChartTooltip anchor={active !== null ? anchor : null}>
        {active !== null && <ChartTooltipContent title={nameAt(active)}>
          <ChartTooltipRow label={label} value={data[active] === null ? EMPTY_VALUE : valueFormat(data[active]!)}/>
        </ChartTooltipContent>}
      </ChartTooltip>
    </>}
  </div>;
}

// ---------- Status ----------

type StatusBarBucket = {
  /** The bucket's name: a date, an hour. Shown under the strip ends and in the tooltip. */
  label: string;
  /** Runs, deploys, requests in the bucket. 0 is a quiet cell. */
  count: number;
  /** The worst outcome in the bucket. warn and fail override the kind's hue. */
  status?: 'ok' | 'warn' | 'fail';
  /** How many of the count failed or warned, for the tooltip. */
  issues?: number;
  /** Replaces the generated count text in the tooltip and the cell's name: "12 runs, 2 failed, 1 with warnings". */
  description?: string;
};

const statusBarVariants = cva('flex w-full min-w-0', {
  variants: {
    size: {
      sm: 'h-4',
      default: 'h-(--row-sm)',
      lg: 'h-(--row)',
    },
  },
  defaultVariants: {size: 'default'},
});

type StatusBarProps = Omit<React.ComponentProps<'div'>, 'children'> & VariantProps<typeof statusBarVariants> & {
  data: StatusBarBucket[];
  /** What the strip shows: "Runs, last 90 days". Names the cells group and the table. */
  label: string;
  /** The kind of thing being counted. Sets the activity hue; ink without one. */
  kind?: Kind;
  /** The noun for count, singular and plural. */
  unit?: [string, string];
  /** Text under the strip's left and right ends. Defaults to the first and last bucket labels. */
  range?: [React.ReactNode, React.ReactNode] | false;
  /** Called when a cell is clicked or pressed with Enter or Space, e.g. to open the logs for that bucket. */
  onBucketClick?: (bucket: StatusBarBucket, index: number) => void;
};

const statusWords = {ok: 'OK', warn: 'Warning', fail: 'Failed'} as const;

function StatusBar({data, label, kind, unit = ['run', 'runs'], range, onBucketClick, size = 'default', className, ...props}: StatusBarProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<{x: number; y: number} | null>(null);
  const cells = useRef<(HTMLElement | null)[]>([]);
  const show = (i: number, el?: HTMLElement | null) => {
    setActive(i);
    const rect = (el ?? cells.current[i])?.getBoundingClientRect();
    if (rect) setAnchor({x: rect.left + rect.width / 2, y: rect.top});
  };
  const hide = () => { setActive(null); setAnchor(null); };
  const roving = useRovingPoints(data.length, (i, el) => show(i, el));
  const noun = (n: number) => `${n.toLocaleString('en-US')} ${n === 1 ? unit[0] : unit[1]}`;
  const describe = (b: StatusBarBucket) => {
    if (b.description) return b.description;
    const parts = [b.count ? noun(b.count) : `No ${unit[1]}`];
    if (b.status && b.status !== 'ok') parts.push(`${b.issues ?? ''} ${b.status === 'fail' ? 'failed' : 'with warnings'}`.trim());
    return parts.join(', ');
  };
  const ends = range === false ? null : range ?? [data[0]?.label, data[data.length - 1]?.label];
  // Whole-pixel cells: the strip's width shared out in integers, a pixel more to some cells than others,
  // so no cell edge lands between pixels and blurs at 1x. Until measured, cells flex.
  const [stripRef, stripWidth] = useElementWidth<HTMLDivElement>();
  const gapPx = data.length > 60 ? 1 : 2;
  const avail = stripWidth - gapPx * (data.length - 1);
  const cellWidth = (i: number) => (stripWidth && avail >= data.length ? Math.floor(((i + 1) * avail) / data.length) - Math.floor((i * avail) / data.length) : undefined);

  return <div ref={ref} data-slot="status-bar" data-kind={kind} className={cn('flex w-full min-w-0 flex-col gap-2', className)} {...props}>
    <ChartDataTable
      caption={label}
      rowHeader="Bucket"
      columns={[{key: 'count', label: unit[1][0].toUpperCase() + unit[1].slice(1)}, {key: 'status', label: 'Status'}]}
      rows={data.map((b, i) => ({key: String(i), label: b.label, values: {count: b.count.toLocaleString('en-US'), status: b.count ? statusWords[b.status ?? 'ok'] : EMPTY_VALUE}}))}
      empty={CHART_EMPTY}
    />
    <div
      ref={stripRef}
      role="group"
      aria-label={label}
      aria-roledescription="status bar"
      className={cn(statusBarVariants({size}), data.length > 60 ? 'gap-px' : 'gap-0.5')}
      onPointerLeave={() => { if (!ref.current?.contains(document.activeElement)) hide(); }}
    >
      {data.map((b, i) => {
        const tone = b.count === 0 ? 'quiet' : b.status === 'warn' || b.status === 'fail' ? b.status : 'active';
        return <button
          key={i}
          ref={el => { cells.current[i] = el; roving.ref(i)(el); }}
          type="button"
          tabIndex={roving.tabIndex(i)}
          data-slot="status-bar-cell"
          data-tone={tone}
          data-status={tone === 'warn' || tone === 'fail' ? tone : undefined}
          aria-label={`${b.label}: ${describe(b)}`}
          onPointerEnter={event => { roving.setCurrent(i); show(i, event.currentTarget); }}
          onFocus={event => { roving.setCurrent(i); show(i, event.currentTarget); }}
          onBlur={event => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node)) hide(); }}
          onKeyDown={event => { if (event.key === 'Escape') hide(); else roving.onKeyDown(event, i); }}
          onClick={onBucketClick && (() => onBucketClick(b, i))}
          style={cellWidth(i) ? {width: cellWidth(i), flex: 'none'} : undefined}
          className={cn(
            'h-full min-w-px flex-1 rounded-none transition-opacity duration-(--dur-fast)',
            tone === 'quiet' ? 'bg-cell-quiet forced-colors:bg-[Canvas]' : 'bg-accent-line forced-colors:bg-[CanvasText]',
            tone !== 'quiet' && 'forced-colors:outline forced-colors:outline-1 forced-colors:-outline-offset-1',
            active !== null && active !== i && 'opacity-(--stale-opacity)',
          )}
        />;
      })}
    </div>
    {ends && <div aria-hidden className="flex justify-between gap-4 type-label-sm text-text-3"><span>{ends[0]}</span><span>{ends[1]}</span></div>}
    <ChartTooltip anchor={active !== null ? anchor : null}>
      {active !== null && data[active] && <ChartTooltipContent title={data[active].label}>
        <ChartTooltipRow
          indicator={<Status status={data[active].count === 0 ? 'idle' : data[active].status ?? 'ok'}/>}
          label={data[active].count ? statusWords[data[active].status ?? 'ok'] : 'Quiet'}
          value={describe(data[active])}
        />
      </ChartTooltipContent>}
    </ChartTooltip>
  </div>;
}

export {
  Sparkline, sparklineVariants,
  StatusBar, statusBarVariants,
  type SparklineProps, type StatusBarProps, type StatusBarBucket,
};
